public class FinallyOrder {
    static int f() {
        try {
            System.out.println("try");
            return 1;
        } finally {
            System.out.println("finally");
        }
    }

    @SuppressWarnings("finally")
    static int g() {
        try {
            throw new IllegalStateException("lost");
        } finally {
            return 2;   // swallows the exception
        }
    }

    static int h() {
        int x = 10;
        try {
            return x;
        } finally {
            x = 99;     // does not change the value already chosen to return
        }
    }

    public static void main(String[] args) {
        System.out.println(f());
        System.out.println(g());
        System.out.println(h());
    }
}

public class Suppressed {
    static class Res implements AutoCloseable {
        private final String name;
        Res(String name) { this.name = name; System.out.println("open " + name); }
        void work() { throw new IllegalStateException("work failed on " + name); }
        @Override public void close() {
            System.out.println("close " + name);
            throw new IllegalArgumentException("close failed on " + name);
        }
    }

    public static void main(String[] args) {
