public class Cost {
    static class Quiet extends RuntimeException {
        Quiet() { super("q", null, false, false); }
    }
    static int sink;
    static void deep(int n, boolean quiet) {
        if (n == 0) throw quiet ? new Quiet() : new RuntimeException("x");
        deep(n - 1, quiet);
    }
    static long run(boolean quiet) {
        long t = System.nanoTime();
        for (int i = 0; i < 200_000; i++) {
            try { deep(50, quiet); } catch (RuntimeException e) { sink++; }
        }
        return (System.nanoTime() - t) / 1_000_000;
    }
    public static void main(String[] args) {
        run(false); run(true); // warm up
        System.out.println("with stack trace   : " + run(false) + " ms");
        System.out.println("without stack trace: " + run(true) + " ms");
    }
}

