public class Charsets {
    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (Writer w = new OutputStreamWriter(bytes, StandardCharsets.UTF_8)) {
            w.write("café ₹");
        }
        byte[] data = bytes.toByteArray();
        System.out.println("bytes: " + data.length);

        for (Charset cs : new Charset[] {StandardCharsets.UTF_8, StandardCharsets.ISO_8859_1,
                                         StandardCharsets.US_ASCII}) {
            try (Reader r = new InputStreamReader(new ByteArrayInputStream(data), cs)) {
                char[] buf = new char[20];
                int n = r.read(buf);
                String s = new String(buf, 0, n);
                System.out.println(cs + " -> " + s.chars()
                    .mapToObj(c -> String.format("%04X", c)).collect(Collectors.joining(" ")));
            }
        }
        System.out.println("default charset: " + Charset.defaultCharset());
    }
}

import java.io.*;

public class Copy {
    static long copyUnbuffered(File src, File dst) throws IOException {
        long t = System.nanoTime();
        try (InputStream in = new FileInputStream(src);
             OutputStream out = new FileOutputStream(dst)) {
            int b;
            while ((b = in.read()) != -1) out.write(b);
        }
        return (System.nanoTime() - t) / 1_000_000;
    }

    static long copyBuffered(File src, File dst) throws IOException {
        long t = System.nanoTime();
        try (InputStream in = new BufferedInputStream(new FileInputStream(src));
             OutputStream out = new BufferedOutputStream(new FileOutputStream(dst))) {
            int b;
            while ((b = in.read()) != -1) out.write(b);
        }
        return (System.nanoTime() - t) / 1_000_000;
    }

    static long copyBlock(File src, File dst) throws IOException {
        long t = System.nanoTime();
        try (InputStream in = new FileInputStream(src);
             OutputStream out = new FileOutputStream(dst)) {
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) != -1) out.write(buf, 0, n);
        }
        return (System.nanoTime() - t) / 1_000_000;
    }

    public static void main(String[] args) throws IOException {
        File src = File.createTempFile("src", ".bin");
        File dst = File.createTempFile("dst", ".bin");
        src.deleteOnExit(); dst.deleteOnExit();
        try (OutputStream o = new BufferedOutputStream(new FileOutputStream(src))) {
            for (int i = 0; i < 500_000; i++) o.write(i);
        }
        copyBuffered(src, dst); // warm-up
        System.out.println("byte by byte, unbuffered : " + copyUnbuffered(src, dst) + " ms");
        System.out.println("byte by byte, buffered   : " + copyBuffered(src, dst) + " ms");
        System.out.println("8 KiB block copy         : " + copyBlock(src, dst) + " ms");
    }
}

