import java.io.IOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;

public class Visitor {
    static void deleteTree(Path root) throws IOException {
        Files.walkFileTree(root, new SimpleFileVisitor<>() {
            @Override public FileVisitResult visitFile(Path f, BasicFileAttributes a)
                    throws IOException {
                Files.delete(f);
                return FileVisitResult.CONTINUE;
            }
            @Override public FileVisitResult postVisitDirectory(Path d, IOException e)
                    throws IOException {
                Files.delete(d);
                return FileVisitResult.CONTINUE;
            }
        });
    }
    public static void main(String[] args) throws IOException {
        Path root = Files.createTempDirectory("tree");
        Files.createDirectories(root.resolve("a/b"));
        Files.writeString(root.resolve("a/one.txt"), "1");
        Files.writeString(root.resolve("a/b/two.txt"), "22");
        long[] total = {0};
        Files.walkFileTree(root, new SimpleFileVisitor<>() {
            @Override public FileVisitResult visitFile(Path f, BasicFileAttributes a) {
                total[0] += a.size();
                System.out.println("file " + root.relativize(f) + " (" + a.size() + " bytes)");
                return FileVisitResult.CONTINUE;
            }
        });
        System.out.println("total bytes: " + total[0]);
        deleteTree(root);
        System.out.println("deleted, exists? " + Files.exists(root));
    }
}

