import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

public class Http {
    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/books/1", ex -> {
            String json = "{\"id\":1,\"title\":\"Effective Java\"}";
            byte[] body = json.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Content-Type", "application/json");
            ex.sendResponseHeaders(200, body.length);
            try (var os = ex.getResponseBody()) { os.write(body); }
        });
        server.start();
        int port = server.getAddress().getPort();

        HttpClient client = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(3)).build();
        URI uri = URI.create("http://127.0.0.1:" + port + "/books/1");
        HttpRequest req = HttpRequest.newBuilder(uri)
            .header("Accept", "application/json").timeout(Duration.ofSeconds(5)).GET().build();

        HttpResponse<String> res = client.send(req, HttpResponse.BodyHandlers.ofString());
        String type = res.headers().firstValue("content-type").orElse("?");
        System.out.println(res.statusCode() + " " + type);
        System.out.println(res.body());

        client.sendAsync(req, HttpResponse.BodyHandlers.ofString())
              .thenApply(HttpResponse::body)
              .thenAccept(b -> System.out.println("async: " + b.length() + " chars"))
              .join();
        server.stop(0);
    }
}

