        System.out.println("maxMemory MB: " + rt.maxMemory() / (1024 * 1024));

        Properties p = new Properties();
        p.setProperty("db.url", "jdbc:h2:mem:test");
        p.setProperty("db.pool", "5");
        StringWriter sw = new StringWriter();
        p.store(sw, "app config");
        String text = sw.toString().lines().filter(l -> !l.startsWith("#")).sorted()
            .reduce("", (a, b) -> a + b + "\n");
        System.out.print(text);
        Properties q = new Properties();
        q.load(new StringReader("# comment\nname = Library \\\n  App\nport=9090\nempty=\n"));
        System.out.println("name='" + q.getProperty("name") + "' port=" + q.getProperty("port")
            + " missing=" + q.getProperty("x") + " dflt=" + q.getProperty("x", "none"));

