import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Properties;

public class ConfigLoader {
    static Properties load(String resource) throws IOException {
        Properties props = new Properties();
        try (InputStream in = ConfigLoader.class.getResourceAsStream(resource)) {
            if (in == null) {
                throw new IOException("resource not found: " + resource);
            }
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                props.load(r);
            }
        }
        return props;
    }

    public static void main(String[] args) throws IOException {
        try {
            load("/app.properties");
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class Proc {
    public static void main(String[] args) throws Exception {
        ProcessBuilder pb = new ProcessBuilder("sh", "-c", "echo out; echo err 1>&2; exit 4");
        pb.redirectErrorStream(true);
        Process p = pb.start();
        try (BufferedReader r = new BufferedReader(
                new InputStreamReader(p.getInputStream(), StandardCharsets.UTF_8))) {
            r.lines().forEach(l -> System.out.println("child> " + l));
        }
        System.out.println("exit code " + p.waitFor());

        Process slow = new ProcessBuilder("sleep", "5").start();
        boolean done = slow.waitFor(300, TimeUnit.MILLISECONDS);
        System.out.println("finished in time? " + done);
        slow.destroy();
        slow.waitFor();
        System.out.println("alive after destroy: " + slow.isAlive());

        ProcessBuilder env = new ProcessBuilder("sh", "-c", "echo $GREETING from $PWD")
            .directory(new File("/tmp"));
        env.environment().put("GREETING", "hello");
        env.redirectErrorStream(true);
        Process e = env.start();
        System.out.print(new String(e.getInputStream().readAllBytes(), StandardCharsets.UTF_8));
        e.waitFor();
        System.out.println("pid positive: " + (ProcessHandle.current().pid() > 0));
    }
}
